def backfill_tenant_identifiers_and_memberships(apps, schema_editor):
    database = schema_editor.connection.alias
    Tenant = apps.get_model('core', 'Tenant')
    TenantMembership = apps.get_model('core', 'TenantMembership')
    User = apps.get_model('users', 'User')

    for tenant in Tenant.objects.using(database).all().iterator():
        updates = {}
        if not tenant.public_id:
            updates['public_id'] = uuid.uuid4()
        if not tenant.code:
            updates['code'] = tenant.slug
        if updates:
            Tenant.objects.using(database).filter(pk=tenant.pk).update(**updates)

    memberships = []
    for user in User.objects.using(database).filter(
        tenant__isnull=False,
        is_platform_admin=False,
    ).iterator():
        memberships.append(TenantMembership(
            tenant_id=user.tenant_id,
            user_id=user.pk,
            role=user.role if user.role in {'admin', 'sales', 'stock'} else 'other',
            is_active=user.is_active,
        ))
    TenantMembership.objects.using(database).bulk_create(
        memberships,
        ignore_conflicts=True,
        batch_size=500,
    )

    tenant_ids = TenantMembership.objects.using(database).filter(
        role='admin',
        is_active=True,
    ).order_by().values_list('tenant_id', flat=True).distinct()
    for tenant_id in tenant_ids.iterator():
        admin = TenantMembership.objects.using(database).filter(
            tenant_id=tenant_id,
            role='admin',
            is_active=True,
        ).order_by('user_id').first()
        if admin:
            TenantMembership.objects.using(database).filter(
                pk=admin.pk,
            ).update(is_primary_admin=True)


